<?php
require_once 'app_bootstrap.php';require_once 'db.php';require_once 'security.php';
if(!customer_is_logged_in())redirect_with_message('reglog.php','Please sign in to review your trip.');
$bookingId=filter_input(INPUT_GET,'booking_id',FILTER_VALIDATE_INT)?:0;
try{$db=db_connect();ensure_app_schema($db);$booking=$db->execute_query("SELECT b.*,p.name package_name,r.id review_id,r.package_rating,r.hotel_rating,r.review_text,r.status review_status FROM bookings b LEFT JOIN packages p ON p.id=b.package_id LEFT JOIN booking_reviews r ON r.booking_id=b.id WHERE b.id=? AND b.user_email=?",[$bookingId,$_SESSION['user_email']])->fetch_assoc();if(!$booking)throw new RuntimeException('Booking not found.');if($booking['status']!=='completed')throw new RuntimeException('Reviews open after the trip is completed.');}catch(Throwable $error){redirect_with_message('my-bookings.php',$error->getMessage());}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review Trip | Travel India</title><link rel="icon" href="img/favicon.jpg?v=1"><link rel="stylesheet" href="css/portal.css?v=17"></head><body class="trips-body"><?php include 'header.php';?>
<main class="portal-page request-page"><header class="portal-heading"><div><span><?php echo e($booking['booking_reference']?:'Booking #'.$booking['id']);?></span><h1>Review your trip</h1><p><?php echo e($booking['package_name']?:$booking['destination']);?> · <?php echo e(date('d M Y',strtotime($booking['from_date'])));?> to <?php echo e(date('d M Y',strtotime($booking['to_date'])));?></p></div><a class="portal-button secondary" href="my-bookings.php#booking-<?php echo (int)$booking['id'];?>">Back to My Trips</a></header>
<section class="request-panel"><?php if($booking['review_id']):?><div class="request-notice"><i class="fa-solid fa-star"></i><p>Your review is submitted. Package: <?php echo (int)$booking['package_rating'];?>/5 · Accommodation: <?php echo (int)$booking['hotel_rating'];?>/5 · Status: <?php echo e(str_replace('_',' ',$booking['review_status']));?></p></div><?php if($booking['review_text']):?><div class="trip-detail"><b>Your review</b><p><?php echo nl2br(e($booking['review_text']));?></p></div><?php endif;?><?php else:?><form class="request-form" method="post" action="booking-review-submit.php"><?php echo csrf_input();?><input type="hidden" name="booking_id" value="<?php echo (int)$booking['id'];?>"><label>Package rating<select name="package_rating" required><option value="">Select rating</option><?php for($i=5;$i>=1;$i--):?><option value="<?php echo $i;?>"><?php echo $i;?> star<?php echo $i===1?'':'s';?></option><?php endfor;?></select></label><label>Accommodation service rating<select name="hotel_rating" required><option value="">Select rating</option><?php for($i=5;$i>=1;$i--):?><option value="<?php echo $i;?>"><?php echo $i;?> star<?php echo $i===1?'':'s';?></option><?php endfor;?></select></label><label>Review <small>Optional</small><textarea name="review_text" maxlength="1000" placeholder="Tell us about the package, accommodation service, and overall experience"></textarea></label><button class="portal-button" type="submit"><i class="fa-solid fa-star"></i> Submit review</button></form><?php endif;?></section></main><?php include 'footer.php';?></body></html>
